update proyectos_sociales set traducciones = '{"en":{"nombre":"Apple seeds planted","descripcion":"We buy and plant apple seeds with highland farming families to help diversify their crops.","unidad":"seeds","unidad_singular":"seed"},"it":{"nombre":"Semi di melo piantati","descripcion":"Acquistiamo e piantiamo semi di melo con le famiglie contadine d''altura per diversificare le loro colture.","unidad":"semi","unidad_singular":"seme"},"fr":{"nombre":"Graines de pommier semées","descripcion":"Nous achetons et semons des graines de pommier avec des familles des hauteurs pour diversifier leurs cultures.","unidad":"graines","unidad_singular":"graine"},"zh":{"nombre":"已播种的苹果种子","descripcion":"我们购买苹果种子，并与高海拔地区的家庭一起播种，帮助他们实现作物多样化。","unidad":"粒种子","unidad_singular":"粒种子"}}'::jsonb where slug = 'semillas-manzano';
