update ajustes set traducciones = '{"en":{"valor":"They leave Costa Rica as pupae and emerge in your butterfly house."},"it":{"valor":"Partono come pupe dalla Costa Rica e sfarfallano nella tua casa delle farfalle."},"fr":{"valor":"Chrysalides au départ du Costa Rica, papillons à l''arrivée dans votre serre."},"zh":{"valor":"以蛹的形态从哥斯达黎加启程，在您的蝴蝶馆中破蛹而出。"}}'::jsonb where clave = 'inicio_titular';
update ajustes set traducciones = '{"en":{"valor":"We supply eight tropical species and export them live to butterfly houses, museums and science centers. We work with Costa Rican breeders, keep a recorded cold chain from end to end, and replace every pupa that doesn''t emerge."},"it":{"valor":"Commercializziamo otto specie tropicali e le esportiamo vive a case delle farfalle, musei e centri scientifici. Lavoriamo con allevamenti costaricani, con una catena del freddo registrata dall''inizio alla fine, e sostituiamo ogni pupa che non si schiude."},"fr":{"valor":"Nous commercialisons huit espèces tropicales et les exportons vivantes vers des serres à papillons, des musées et des centres de sciences. Nous travaillons avec des élevages costaricains, avec une chaîne du froid enregistrée de bout en bout et le remplacement de toute chrysalide qui n''éclot pas."},"zh":{"valor":"我们经营八个热带蝴蝶品种，以活体形式出口至蝴蝶馆、博物馆和科学中心。我们与哥斯达黎加养殖户合作，全程冷链均有温度记录，任何未能羽化的蛹都将免费补发。"}}'::jsonb where clave = 'inicio_entradilla';
