update ajustes set traducciones = '{"en":{"valor":"A pupa holds for ten to fourteen days before it emerges. Every step is timed so it arrives with room to spare, not just in time."},"it":{"valor":"La pupa resiste da dieci a quattordici giorni prima di schiudersi. Tutto il processo è calibrato perché arrivi con margine, non all''ultimo momento."},"fr":{"valor":"La chrysalide tient entre dix et quatorze jours avant d''éclore. Tout le processus est calibré pour qu''elle arrive avec de la marge, et non tout juste."},"zh":{"valor":"蛹在羽化前可维持十到十四天。整个流程都经过精心安排，确保货物留有充足余量送达，而不是踩着时间点。"}}'::jsonb where clave = 'ciclo_texto';
update ajustes set traducciones = '{"en":{"valor":"0|Confirmation|We lock in species, quantities and flight date.\n3|Collection and selection|We receive pupae from our breeders and discard any that look doubtful.\n5|Cold packing|Cotton, cooling gel and a temperature logger.\n9|Delivery|Customs, phytosanitary inspection and on to your butterfly house door."},"it":{"valor":"0|Conferma|Definiamo specie, quantità e data di volo.\n3|Raccolta e selezione|Riceviamo le pupe dagli allevamenti e scartiamo quelle dubbie.\n5|Imballaggio refrigerato|Cotone, gel refrigerante e registratore di temperatura.\n9|Consegna|Dogana, ispezione fitosanitaria e consegna alla porta della tua casa delle farfalle."},"fr":{"valor":"0|Confirmation|Nous arrêtons les espèces, les quantités et la date du vol.\n3|Collecte et tri|Nous réceptionnons les chrysalides des élevages et écartons toute chrysalide douteuse.\n5|Emballage réfrigéré|Coton, gel réfrigérant et enregistreur de température.\n9|Livraison|Douane, inspection phytosanitaire et livraison jusqu''à la porte de votre serre à papillons."},"zh":{"valor":"0|确认订单|确定品种、数量和航班日期。\n3|收集与筛选|从养殖户处收货，剔除一切存疑的蛹。\n5|冷藏包装|棉垫、冷却凝胶和温度记录仪。\n9|送达|清关、植物检疫查验，直至送到蝴蝶馆门口。"}}'::jsonb where clave = 'ciclo_pasos';
update ajustes set traducciones = '{"en":{"valor":"Minimum per species|25 pupae\nTransit temperature|13 °C to 16 °C\nDocuments included|CITES permit and phytosanitary certificate\nNon-viable pupae|Replaced free of charge in your next shipment"},"it":{"valor":"Minimo per specie|25 pupe\nTemperatura di transito|Da 13 °C a 16 °C\nDocumenti inclusi|Permesso CITES e certificato fitosanitario\nPupe non vitali|Sostituite senza costi nella spedizione successiva"},"fr":{"valor":"Minimum par espèce|25 chrysalides\nTempérature de transit|13 °C à 16 °C\nDocuments inclus|Permis CITES et certificat phytosanitaire\nChrysalides non viables|Remplacées gratuitement lors de l''envoi suivant"},"zh":{"valor":"每个品种起订量|25 枚蛹\n运输温度|13 °C 至 16 °C\n随附文件|CITES 许可证及植物检疫证书\n无法羽化的蛹|在下一批货物中免费补发"}}'::jsonb where clave = 'envio_condiciones';
update ajustes set traducciones = '{"en":{"valor":"They''re exported as pupae, the stage at which the insect best withstands travel. They ship in cotton-lined trays with cooling gel and a temperature logger that''s read when the box is opened."},"it":{"valor":"Vengono esportate allo stadio di pupa, la fase in cui l''insetto sopporta meglio il viaggio. Viaggiano in vassoi di cotone con gel refrigerante e un registratore di temperatura che si legge all''apertura della scatola."},"fr":{"valor":"Elles sont exportées au stade de chrysalide, lorsque l''insecte supporte le mieux le transport. Elles voyagent sur des plateaux de coton avec du gel réfrigérant et un enregistreur de température, relevé à l''ouverture du colis."},"zh":{"valor":"蝴蝶以蛹的形态出口，这是昆虫最能承受运输的阶段。蛹装在铺有棉垫的托盘中，配有冷却凝胶和温度记录仪，开箱时即可读取温度数据。"}}'::jsonb where clave = 'envio_texto';

notify pgrst, 'reload schema';
